#include "stdlib/blas/base/dgemm.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/xerbla.h"

/**
* Performs the matrix-matrix operation `C = alpha*op(A)*op(B) + beta*C`, using alternative indexing semantics and where `op(X)` is either `op(X) = X` or `op(X) = X^T`, `alpha` and `beta` are scalars, and `A`, `B`, and `C` are matrices, with `op(A)` an `M`-by-`K` matrix, `op(B)` a `K`-by-`N` matrix, and `C` an `M`-by-`N` matrix.
*
* @param transA    specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param transB    specifies whether `B` should be transposed, conjugate-transposed, or not transposed
* @param M         number of rows in `op(A)` and `C`
* @param N         number of columns in `op(B)` and `C`
* @param K         number of columns in `op(A)` and rows in `op(B)`
* @param alpha     scalar constant
* @param A         first matrix
* @param strideA1  stride of the first dimension of `A`
* @param strideA2  stride of the second dimension of `A`
* @param offsetA   starting index for `A`
* @param B         second matrix
* @param strideB1  stride of the first dimension of `B`
* @param strideB2  stride of the second dimension of `B`
* @param offsetB   starting index for `B`
* @param beta      scalar constant
* @param C         result matrix
* @param strideC1  stride of the first dimension of `C`
* @param strideC2  stride of the second dimension of `C`
* @param offsetC   starting index for `C`
*/
void API_SUFFIX(c_dgemm_ndarray)( const CBLAS_TRANSPOSE transA, const CBLAS_TRANSPOSE transB, const CBLAS_INT M, const CBLAS_INT N, const CBLAS_INT K, const double alpha, const double *A, const CBLAS_INT strideA1, const CBLAS_INT strideA2, const CBLAS_INT offsetA, const double *B, const CBLAS_INT strideB1, const CBLAS_INT strideB2, const CBLAS_INT offsetB, const double beta, double *C, const CBLAS_INT strideC1, const CBLAS_INT strideC2, const CBLAS_INT offsetC ) {
	CBLAS_INT da_row; // stride along rows of op(A), i.e., iterates over M
	CBLAS_INT da_col; // stride along cols of op(A), i.e., iterates over K
	CBLAS_INT db_row; // stride along rows of op(B), i.e., iterates over K
	CBLAS_INT db_col; // stride along cols of op(B), i.e., iterates over N
	CBLAS_INT ia;
	CBLAS_INT ib;
	CBLAS_INT ic;
	CBLAS_INT i;
	CBLAS_INT j;
	CBLAS_INT l;
	double temp;

	// Validate input arguments...
	if ( M < 0 ) {
		c_xerbla( 3, "c_dgemm_ndarray", "Error: invalid argument. Third argument must be a nonnegative integer. Value: `%d`.", M );
		return;
	}
	if ( N < 0 ) {
		c_xerbla( 4, "c_dgemm_ndarray", "Error: invalid argument. Fourth argument must be a nonnegative integer. Value: `%d`.", N );
		return;
	}
	if ( K < 0 ) {
		c_xerbla( 5, "c_dgemm_ndarray", "Error: invalid argument. Fifth argument must be a nonnegative integer. Value: `%d`.", K );
		return;
	}
	// Quick return if possible...
	if ( M == 0 || N == 0 || ( ( alpha == 0.0 || K == 0 ) && beta == 1.0 ) ) {
		return;
	}
	// Scale C by beta (handle beta == 0 and beta == 1 as special cases)...
	if ( beta == 0.0 ) {
		ic = offsetC;
		for ( i = 0; i < M; i++ ) {
			for ( j = 0; j < N; j++ ) {
				C[ ic + (j * strideC2) ] = 0.0;
			}
			ic += strideC1;
		}
	} else if ( beta != 1.0 ) {
		ic = offsetC;
		for ( i = 0; i < M; i++ ) {
			for ( j = 0; j < N; j++ ) {
				C[ ic + (j * strideC2) ] *= beta;
			}
			ic += strideC1;
		}
	}
	// Check whether we can early return after scaling...
	if ( alpha == 0.0 || K == 0 ) {
		return;
	}
	/*
	* Resolve strides for op(A) and op(B).
	*
	* If transA == CblasNoTrans: op(A)[i,l] = A[offsetA + i*strideA1 + l*strideA2]
	*   → da_row = strideA1 (iterate over rows i = 0..M-1)
	*   → da_col = strideA2 (iterate over cols l = 0..K-1)
	*
	* If transA == CblasTrans: op(A)[i,l] = A[offsetA + l*strideA1 + i*strideA2]
	*   → da_row = strideA2 (iterate over rows i = 0..M-1)
	*   → da_col = strideA1 (iterate over cols l = 0..K-1)
	*/
	if ( transA == CblasNoTrans ) {
		da_row = strideA1;
		da_col = strideA2;
	} else {
		da_row = strideA2;
		da_col = strideA1;
	}
	if ( transB == CblasNoTrans ) {
		db_row = strideB1;
		db_col = strideB2;
	} else {
		db_row = strideB2;
		db_col = strideB1;
	}
	// Compute C += alpha * op(A) * op(B)...
	ic = offsetC;
	for ( i = 0; i < M; i++ ) {
		for ( j = 0; j < N; j++ ) {
			// Compute dot product of row i of op(A) with col j of op(B)...
			ia = offsetA + ( i * da_row );
			ib = offsetB + ( j * db_col );
			temp = 0.0;
			for ( l = 0; l < K; l++ ) {
				temp += A[ ia ] * B[ ib ];
				ia += da_col;
				ib += db_row;
			}
			C[ ic + (j * strideC2) ] += alpha * temp;
		}
		ic += strideC1;
	}
	return;
}
